CREATE TABLE lsh_matters(id uuid PRIMARY KEY,reference varchar(30) NOT NULL UNIQUE,title varchar(255) NOT NULL,type varchar(50) NOT NULL,sub_category varchar(255) NOT NULL,status varchar(60) NOT NULL,urgency varchar(30) NOT NULL,requester_id varchar(255) NOT NULL,requester_name varchar(255),business_unit varchar(255) NOT NULL,counterparty varchar(255),requested_service varchar(6000),background varchar(12000),trigger_date date,due_date date,owner_id varchar(255),owner_name varchar(255),pending_reason varchar(255),restricted_matter boolean NOT NULL DEFAULT false,invoice_number varchar(255),amount numeric(19,2),payment_due_date date,agreement_reference varchar(255),court varchar(255),insurance_relevant boolean NOT NULL DEFAULT false,commercial_rationale varchar(255),review_perspective varchar(255),version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL);
CREATE INDEX lsh_idx_matters_status ON matters(status);CREATE INDEX idx_matters_due_date ON matters(due_date);CREATE INDEX idx_matters_requester ON matters(requester_id);CREATE INDEX idx_matters_owner ON matters(owner_id);
CREATE TABLE lsh_documents(id uuid PRIMARY KEY,matter_id uuid NOT NULL REFERENCES matters(id),file_name varchar(255) NOT NULL,content_type varchar(255) NOT NULL,size_bytes bigint NOT NULL,category varchar(60) NOT NULL,external_id varchar(1000),web_url varchar(2000),uploaded_by varchar(255) NOT NULL,uploaded_at timestamptz NOT NULL);CREATE INDEX idx_documents_matter ON documents(matter_id);
CREATE TABLE lsh_audit_events(id uuid PRIMARY KEY,matter_id uuid,action varchar(255) NOT NULL,actor_id varchar(255) NOT NULL,actor_name varchar(255),details text,occurred_at timestamptz NOT NULL);CREATE INDEX idx_audit_matter_time ON audit_events(matter_id,occurred_at DESC);
CREATE TABLE lsh_feedback(id uuid PRIMARY KEY,matter_id uuid NOT NULL UNIQUE REFERENCES matters(id),rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5),comment varchar(4000),submitted_by varchar(255) NOT NULL,submitted_at timestamptz NOT NULL);
